// Package ui renders the local EasyScan dashboard and its self-contained
// offline-report variant. No third-party assets are needed at runtime.
package ui

import (
	"bytes"
	"encoding/json"
	"fmt"
	"html/template"
	"time"

	"github.com/example/easyscan/internal/model"
)

type payload struct {
	Mode        string          `json:"mode"`
	GeneratedAt string          `json:"generatedAt"`
	Findings    []model.Finding `json:"findings"`
	Assets      []model.Asset   `json:"assets"`
}

// Render produces a fully self-contained dashboard. Live dashboards fetch
// fresh data from the same-origin API; static reports use the embedded data.
func Render(live bool, findings []model.Finding, assets []model.Asset) ([]byte, error) {
	mode := "static"
	if live {
		mode = "live"
		findings = nil
		assets = nil
	}
	b, err := json.Marshal(payload{Mode: mode, GeneratedAt: time.Now().UTC().Format(time.RFC3339), Findings: findings, Assets: assets})
	if err != nil {
		return nil, fmt.Errorf("encode dashboard data: %w", err)
	}
	t, err := template.New("dashboard").Parse(source)
	if err != nil {
		return nil, fmt.Errorf("parse dashboard template: %w", err)
	}
	var output bytes.Buffer
	// json.Marshal HTML-escapes untrusted text, making it safe to insert as JS.
	if err := t.Execute(&output, map[string]template.JS{"Data": template.JS(b)}); err != nil {
		return nil, fmt.Errorf("render dashboard: %w", err)
	}
	return output.Bytes(), nil
}

